doc.doc:
The Chronological Version parser.

Adapted from {@link https://github.com/ChronVer/chronver | ChronVer}. See
{@link https://chronver.org} for the spec.

```ts
import { format, greaterThan, increment, parse } from "@ende/chronver";
import { assert, assertEquals } from "@ende/assert";

const version = parse("2024.04.03.1");
assertEquals(version, {
  year: 2024,
  month: 4,
  day: 3,
  changeset: 1,
  isBreaking: false
});

assertEquals(format(version), "2024.04.03.1");
assert(greaterThan(parse("2024.04.04"), version));

// Same day: bump the changeset. Another day: that date's version.
assertEquals(format(increment(version, new Date(2024, 3, 3))), "2024.04.03.2");
assertEquals(format(increment(version, new Date(2024, 3, 4))), "2024.04.04");
```

## Format

```
YYYY.MM.DD[.CHANGESET][-FEATURE|-break]
```

| Version                | Description                   |
| ---------------------- | ----------------------------- |
| `2025.07.21`           | Released July 21st, 2025      |
| `2025.07.21.1`         | First hotfix that day         |
| `2025.07.21.3`         | Third change that day         |
| `2025.07.21-feature`   | Feature branch for that date  |
| `2025.07.21.1-feature` | Feature branch with changeset |
| `2025.07.21.1-break`   | Breaking change               |

The date must be a real calendar date: `2024.02.29` is valid, `2023.02.29`
and `2024.04.31` are not. Dates are read and written in local time.

tags.doc:
Usage
```ts
import { canParse } from "@ende/chronver/can-parse";
import { assert, assertFalse } from "@ende/assert";

assert(canParse("2024.02.29")); // 2024 is a leap year
assertFalse(canParse("2023.02.29")); // 2023 is not
assertFalse(canParse("2024.04.31")); // April has 30 days
assertFalse(canParse("invalid"));
```

Usage
```ts
import { parse, compare } from "@ende/chronver";
import { assertEquals } from "@ende/assert";

const version1 = parse("2024.04.03");
const version2 = parse("2024.04.04");

assertEquals(compare(version1, version2), -1);
assertEquals(compare(version2, version1), 1);
assertEquals(compare(version1, version1), 0);
assertEquals(compare(parse("2024.04.03.1-break"), parse("2024.04.03.1")), 1);
```

Usage
```ts
import { parse, equals } from "@ende/chronver";
import { assert, assertFalse } from "@ende/assert";

assert(equals(parse("2024.04.03.1"), parse("2024.04.03.1")));
assertFalse(equals(parse("2024.04.03.1"), parse("2024.04.03.2")));
assert(equals(parse("2024.04.03-a"), parse("2024.04.03-b")));
```

Usage
```ts
import { format } from "@ende/chronver/format";
import { assertEquals } from "@ende/assert";

assertEquals(format({ year: 2024, month: 4, day: 3, changeset: 0, isBreaking: false }), "2024.04.03");
assertEquals(format({ year: 2024, month: 4, day: 3, changeset: 1, feature: "new-ui", isBreaking: false }), "2024.04.03.1-new-ui");
assertEquals(format({ year: 2024, month: 4, day: 3, changeset: 1, isBreaking: true }), "2024.04.03.1-break");
```

Usage
```ts
import { fromDate } from "@ende/chronver/from-date";
import { format } from "@ende/chronver/format";
import { assertEquals } from "@ende/assert";

const date = new Date(2024, 3, 3); // April 3, 2024

assertEquals(format(fromDate(date)), "2024.04.03");
assertEquals(format(fromDate(date, 5)), "2024.04.03.5");
```

